pydough_code:
vldb_keyword = academic.conferences.WHERE(name == "VLDB").publications.publication_keywords.keyword.CALCULATE(
    keyword_name=keyword
).PARTITION(name="keyword_partition", by=keyword_name).CALCULATE(
    keyword_name=keyword_name,
    num_publications=COUNT(keyword)
).TOP_K(1, by=num_publications.DESC())

