pydough_code:
stadium_with_most_concerts = concert_singer.concerts.WHERE(
    year > "2013"
).CALCULATE(
    stad_id=stadium_id
).PARTITION(name="stadium_partition", by=stad_id).CALCULATE(
    stad_id=stad_id,
    num_concerts=COUNT(concerts)
).TOP_K(1, by=num_concerts.DESC()).concerts.stadium.CALCULATE(name=name, capacity=capacity)

