pydough_code:
conductors_with_multiple_orchestras = orchestra.conductors.CALCULATE(
    conductor_id = conductor_id
).WHERE(
    HAS(orchestras) == 1
).PARTITION(
    name="conductor_groups", by=(conductor_id)
).CALCULATE(
    conductor_name = name,
    num_orchestras = COUNT(conductors.orchestras)
).WHERE(num_orchestras > 1).CALCULATE(name = conductor_name)

