pydough_code:
movie_title = "The Past"
movie_info = copyrights.WHERE(
    LIKE(id, "%" + movie_title + "%")
).CALCULATE(
    msid=msid
)
director_info = directed_bies.WHERE(msid == movie_info.SINGULAR().msid).CALCULATE(
    did=did
)
director_birth_city = directors.WHERE(did == director_info.SINGULAR().did).CALCULATE(
    director_birth_city=birth_city
)
result = director_birth_city.SINGULAR().director_birth_city

