pydough_code:
moroccan_checkins = yelp.categories.WHERE(
    category_name == "Moroccan"
).busines.WHERE(
    city == "Los Angeles"
).checkins.PARTITION(name="daily_checkins", by=(day)).CALCULATE(
    day=day,
    total_checkins=SUM(count)
)

