pydough_code:
nips_papers_by_year = scholar.papers.WHERE(venue.venuename == "NIPS").CALCULATE(
    paper_year=year
).PARTITION(name="years", by=paper_year).CALCULATE(
    year=paper_year,
    num_papers=COUNT(papers)
).TOP_K(1, by=num_papers.DESC())

