", "data_type": "string"}, "venueid": {"type": "table_column", "column_name": "venueid", "data_type": "int64"}, "year": {"type": "table_column", "column_name": "year", "data_type": "int64"}, "numciting": {"type": "table_column", "column_name": "numciting", "data_type": "int64"}, "numcitedby": {"type": "table_column", "column_name": "numcitedby", "data_type": "int64"}, "journalid": {"type": "table_column", "column_name": "journalid", "data_type": "int64"}, "venue": {"type": "simple_join", "other_collection_name": "venues", "singular": true, "no_collisions": false, "keys": {"venueid": ["venueid"]}, "reverse_relationship_name": "papers"}, "journal": {"type": "simple_join", "other_collection_name": "journals", "singular": true, "no_collisions": false, "keys": {"journalid": ["journalid"]}, "reverse_relationship_name": "papers"}}}, "paperdatasets": {"type": "simple_table", "table_path": "main.paperDataset", "unique_properties": [["paperid", "datasetid"]], "properties": {"paperid": {"type": "table_column", "column_name": "paperid", "data_type": "int64"}, "datasetid": {"type": "table_column", "column_name": "datasetid", "data_type": "int64"}}}, "paperkeyphrases": {"type": "simple_table", "table_path": "main.paperKeyphrase", "unique_properties": [["paperid", "keyphraseid"]], "properties": {"paperid": {"type": "table_column", "column_name": "paperid", "data_type": "int64"}, "keyphraseid": {"type": "table_column", "column_name": "keyphraseid", "data_type": "int64"}, "keyphrase": {"type": "simple_join", "other_collection_name": "keyphrases", "singular": true, "no_collisions": false, "keys": {"keyphraseid": ["keyphraseid"]}, "reverse_relationship_name": "paperkeyphrases"}, "paper": {"type": "simple_join", "other_collection_name": "papers", "singular": true, "no_collisions": false, "keys": {"paperid": ["paperid"]}, "reverse_relationship_name": "paperkeyphrases"}}}, "venues": {"type": "simple_table", "table_path": "main.venue", "unique_properties": ["venueid"], "properties": {"venueid": {"type": "table_column", "column_name": "venueid", "data_type": "int64"}, "venuename": {"type": "table_column", "column_name": "venuename", "data_type": "string"}}}, "write": {"type": "simple_table", "table_path": "main.writes", "unique_properties": [["paperid", "authorid"]], "properties": {"paperid": {"type": "table_column", "column_name": "paperid", "data_type": "int64"}, "authorid": {"type": "table_column", "column_name": "authorid", "data_type": "int64"}, "author": {"type": "simple_join", "other_collection_name": "authors", "singular": true, "no_collisions": false, "keys": {"authorid": ["authorid"]}, "reverse_relationship_name": "write"}, "paper": {"type": "simple_join", "other_collection_name": "papers", "singular": true, "no_collisions": false, "keys": {"paperid": ["paperid"]}, "reverse_relationship_name": "write"}}}}}

pydough_code:
syntactic_parsing_author = scholar.paperkeyphrases.WHERE(keyphrase.keyphrasename == "syntactic parsing").paper.write.CALCULATE(
    author_name=author.authorname
).PARTITION(name="author_partition", by=author_name).CALCULATE(
    author_name=author_name,
    num_papers=COUNT(write)
).TOP_K(1, by=num_papers.DESC())

