pydough_code:
pldb_citations_per_year = academic.publications.WHERE(
    conference.name == "PVLDB"
).CALCULATE(
    publication_year=YEAR(year)
).PARTITION(
    name="years", by=publication_year
).CALCULATE(
    year=publication_year,
    total_citations=SUM(publications.citation_num)
)

