pydough_code:
most_used_keyword = academic.publications.WHERE(
    (conference.name == "PVLDB") | (journal.name == "PVLDB")
).publication_keywords.CALCULATE(
    keyword_name=keyword.keyword
).PARTITION(name="keyword_partition", by=keyword_name).CALCULATE(
    keyword_name=keyword_name,
    keyword_count=COUNT(publication_keywords)
).TOP_K(1, by=keyword_count.DESC())

