pydough_code:
semantic_parsing_papers = scholar.paperkeyphrases.WHERE(
    keyphrase.keyphrasename == "semantic parsing"
).paper.WHERE(year > 2005)

author_papers = scholar.write.WHERE(
    paperid.ISIN(semantic_parsing_papers.paperid)
).author

most_published_author = author_papers.CALCULATE(
    author_name=authorname, num_papers=COUNT(write)
).TOP_K(1, by=num_papers.DESC())

