pydough_code:
least_paragraphs_document = paragraph.CALCULATE(
    doc_id=document_id
).PARTITION(name='doc_group', by=doc_id).CALCULATE(
    doc_id=doc_id,
    num_paragraphs=COUNT(paragraph)
).TOP_K(1, by=num_paragraphs.ASC()).CALCULATE(document_id=doc_id)

