pydough_code:
woody_allen_movies_per_year = imdb.directors.WHERE(name == " Woody Allen ").directed_bies.copyright.CALCULATE(
    year=YEAR(id)
).PARTITION(name="years", by=year).CALCULATE(
    year=year,
    number_of_movies=COUNT(copyright)
)

