pydough_code:
papers_with_syntactic_parsing_not_by_chris_dyer = scholar.papers.WHERE(
    HAS(paperkeyphrases.keyphrase) == 1
).WHERE(
    paperkeyphrases.keyphrase.keyphrasename == "syntactic parsing"
).WHERE(
    HASNOT(write.author.WHERE(authorname == "chris dyer")) == 1
)

