pydough_code:
deep_learning_venue = scholar.paperkeyphrases.WHERE(
    keyphrase.keyphrasename == "deep learning"
).paper.PARTITION(name="venues", by=venue.venuename).CALCULATE(
    venue_name=venue.venuename, num_papers=COUNT(papers)
).TOP_K(1, by=num_papers.DESC())

