pydough_code:
peter_mertens_papers = scholar.papers.WHERE(
    paperid.ISIN(
        scholar.write.WHERE(
            authorid == scholar.authors.WHERE(authorname == "Peter Mertens").authorid
        ).paperid
    )
)
dina_barbian_papers = scholar.papers.WHERE(
    paperid.ISIN(
        scholar.write.WHERE(
            authorid == scholar.authors.WHERE(authorname == "Dina Barbian").authorid
        ).paperid
    )
)
papers_by_authors = peter_mertens_papers.CALCULATE(title=title, year=year) | dina_barbian_papers.CALCULATE(title=title, year=year)

