pydough_code:
most_papers_at_chi = scholar.venues.WHERE(
    venuename == "chi"
).papers.write.CALCULATE(
    author_name=author.authorname, num_papers=COUNT(paperid)
).TOP_K(1, by=num_papers.DESC())

