pydough_code:
author_name = " H. V. Jagadish "
conference_with_most_papers = academic.authors.WHERE(name == author_name).CALCULATE(
    author_id=aid
).write.CALCULATE(publication_id=publication.pid).publication.CALCULATE(
    conference_id=conference.cid
).conference.CALCULATE(
    conference_name=name, num_papers=COUNT(publications)
).TOP_K(1, by=num_papers.DESC())

