most_cited_ai_paper = scholar.papers.WHERE(
    HAS(paperkeyphrases.keyphrase.WHERE(keyphrasename == "Artificial Intelligence")) == 1
).TOP_K(1, by=numcitedby.DESC()).CALCULATE(
    paper_title=title,
    citation_count=numcitedby
)

