pydough_code:
cafe_zinho_tips = yelp.businesses.WHERE(
    (businesses.name == "Cafe Zinho") & (businesses.state == "PA")
).tips.WHERE(tips.year == "2010").CALCULATE(tip_id=tip_id, business_id=business_id, text=text, user_id=user_id, likes=likes, year=year, month=month)

