pydough_code:
jamie_callan_papers_by_year = scholar.authors.WHERE(authorname == "jamie callan").write.CALCULATE(
    year=YEAR(paper.year)
).PARTITION(name="years", by=year).CALCULATE(
    year=year,
    num_papers=COUNT(write)
)

