pydough_code:
sensor_fusion_publishers = scholar.paperkeyphrases.WHERE(
    keyphrase.keyphrasename == "sensor fusion"
).CALCULATE(
    venue_name=paper.venue.venuename,
    journal_name=paper.journal.journalname
)

