pydough_code:
luke_citations_per_year = scholar.authors.WHERE(authorname == "luke zettlemoyer").write.paper.cites.CALCULATE(
    citing_year=YEAR(paper.year)
).PARTITION(name="years", by=citing_year).CALCULATE(
    year=citing_year,
    num_citations=COUNT(cites)
)

