pydough_code:
richard_ladner_paper = scholar.papers.WHERE(
  (paperid == (
      scholar.write.paperid
      ).WHERE(
          authorid == (
              scholar.authors.authorid
          ).WHERE(authorname == "Richard Ladner")
      )
  ) & (venueid == (scholar.venues.venueid).WHERE(venuename == "chi"))
).CALCULATE(title=title)

