pydough_code:
daniel_reed_citations = scholar.authors.WHERE(authorname == "Daniel A Reed").CALCULATE(
    daniel_reed_id = authorid
).papers.cites.citingpaperid.papers.write.author.CALCULATE(
    author_name = authorname
).PARTITION(name="citing_authors", by=author_name).CALCULATE(
    author_name = author_name,
    citation_count = COUNT(scholar.authors.authorid)
).ORDER_BY(citation_count.DESC())

